create table if not exists executive_briefs (id uuid primary key default gen_random_uuid(),organization_id uuid not null,brief_date date not null,headline text not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(organization_id,brief_date));alter table executive_briefs enable row level security;create policy "organization executive briefs" on executive_briefs using (organization_id=auth.uid()) with check (organization_id=auth.uid());